def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if all(grid[r][c] != 8 for c in range(w))]
    cols = [c for c in range(w) if all(grid[r][c] != 8 for r in range(h))]

    counts = {}
    for row in grid:
        for value in row:
            if value != 8:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    out = []
    for i in range(len(rows) - 1):
        line = []
        for j in range(len(cols) - 1):
            corners = (
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            )
            value = corners[0]
            line.append(value if value != background and all(x == value for x in corners) else 8)
        out.append(line)

    # Remove any all-background outer rows or columns.
    while out and all(x == 8 for x in out[0]):
        out.pop(0)
    while out and all(x == 8 for x in out[-1]):
        out.pop()
    if out:
        while all(row[0] == 8 for row in out):
            for row in out:
                row.pop(0)
        while all(row[-1] == 8 for row in out):
            for row in out:
                row.pop()
    return out
